models.css:
.card {
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", "Heiti SC", sans-serif;
  text-align: center;
  color: #0f172a;
  background-color: #f8fafc;
  padding: 16px 10px;
}
.card-box {
  max-width: 560px;
  margin: 0 auto;
  background: #ffffff;
  border-radius: 18px;
  box-shadow: 0 4px 16px rgba(15, 23, 42, 0.08);
  padding: 24px 20px;
  box-sizing: border-box;
}
.tag-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  font-size: 13px;
  color: #64748b;
}
.badge {
  background: #e0f2fe;
  color: #0369a1;
  font-weight: bold;
  padding: 4px 12px;
  border-radius: 999px;
}
.q-main {
  font-size: 28px;
  font-weight: 800;
  color: #0f172a;
  line-height: 1.6;
  margin: 12px 0;
}
.q-sub {
  font-size: 22px;
  font-weight: 700;
  color: #1e293b;
  line-height: 1.7;
  margin: 8px 0;
}
.blank {
  display: inline-block;
  min-width: 44px;
  height: 44px;
  line-height: 42px;
  text-align: center;
  border: 2.5px solid #334155;
  border-radius: 8px;
  background: #ffffff;
  vertical-align: middle;
  margin: 0 6px;
  padding: 0 6px;
  font-size: 26px;
  font-weight: 800;
  color: #dc2626;
}
.circle-blank {
  display: inline-block;
  width: 42px;
  height: 42px;
  line-height: 38px;
  text-align: center;
  border: 2.5px solid #334155;
  border-radius: 50%;
  background: #ffffff;
  vertical-align: middle;
  margin: 0 8px;
  font-size: 26px;
  font-weight: 800;
  color: #dc2626;
}
.pair-box {
  display: inline-block;
  background: #fffbeb;
  border: 2px solid #fde68a;
  border-radius: 14px;
  padding: 14px 18px;
  margin: 8px auto 14px;
  text-align: left;
}
.pair-table {
  border-collapse: collapse;
  margin: 0 auto;
}
.pair-table td {
  width: 44px;
  text-align: center;
  font-size: 30px;
  padding: 2px 4px;
  line-height: 1.1;
}
.pair-table tr.dots td {
  font-size: 18px;
  color: #94a3b8;
  font-weight: bold;
  padding: 0;
  line-height: 1;
}
.pair-table td.extra {
  background: #fee2e2;
  border-radius: 8px;
}
.ans-divider {
  margin: 18px 0;
  border: none;
  border-top: 2px dashed #cbd5e1;
}
.ans-box {
  background: #f0fdf4;
  border: 2px solid #86efac;
  border-radius: 14px;
  padding: 16px 18px;
  margin-top: 8px;
}
.ans-main {
  font-size: 28px;
  font-weight: 800;
  color: #15803d;
  line-height: 1.6;
}
.ans-tip {
  font-size: 16px;
  color: #334155;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed #bbf7d0;
  line-height: 1.5;
}
.ans-tip b {
  color: #b91c1c;
}
.step-tag {
  display: inline-block;
  background: #fef08a;
  color: #854d0e;
  font-size: 15px;
  font-weight: bold;
  padding: 2px 8px;
  border-radius: 6px;
  margin: 0 3px;
}
